  [889] = { "战歌氏族", "战歌氏族是最具攻击性的兽人氏族，目前正与暗夜精灵的银翼哨兵部队在战歌峡谷激烈地交战中。" },
  [890] = { "银翼要塞", "灰谷地区坚定的守卫者，目前正与战歌氏族在战歌峡谷中激烈交战。" },
  [891] = { "联盟部队" },
  [892] = { "部落军队" },
  [893] = { "恶齿巨魔" },
  [909] = { "暗月马戏团", "一个向全世界展示着各类珍奇异宝的马戏团。马戏团位于一座神秘的岛屿上，只在每月的第一周开放。" },
  [910] = { "诺兹多姆的子嗣", "青铜龙军团的后代，时间的守卫者，对凡人种族漠不关心。" },
  [911] = { "银月城", "奎尔萨拉斯的首都，血精灵的家园。虽然银月城几乎被阿尔萨斯毁灭，但它再次成为了一座繁荣的城市。" },
  [912] = { "卡利姆多联军" },
  [914] = { "玩家，血精灵" },
  [915] = { "克苏恩的军队" },
  [916] = { "异种虫类" },
  [917] = { "铁炉堡军团" },
  [920] = { "红" },
  [921] = { "蓝" },
  [922] = { "塔奎林", "塔奎林曾是一座高等精灵的城镇，但是在天灾军团入侵奎尔萨拉斯之后被废弃了。现在，被遗忘者和血精灵联手夺回了这座城镇。" },
  [923] = { "远行者" },
  [925] = { "逐日者" },
  [926] = { "魔导师公会" },
  [927] = { "玩家，德莱尼" },
  [928] = { "天灾入侵者" },
  [929] = { "血槌氏族" },
  [930] = { "埃索达", "将德莱尼人带到艾泽拉斯世界来的纳鲁飞船，目前搁浅在秘蓝岛上。对于这个高贵的种族来说，埃索达是他们的主城。" },
  [932] = { "奥尔多", "一个古老的德莱尼祭司组织，起初由维伦领导。现在他们在高阶女祭司伊沙娜的指引下为沙塔斯城的纳鲁效力。与占星者势力敌对。" },
  [933] = { "星界财团", "由星界巨商哈拉麦德领导的星界财团是一个结构松散的商业联盟，其成员都是从事走私、贸易或盗窃的虚灵。" },
  [934] = { "占星者", "由先知沃雷塔尔领导的这群血精灵拒绝跟随凯尔萨斯。他们加入了沙塔斯城的纳鲁联军，这令奥尔多感到非常不安。" },
  [935] = { "沙塔尔", "沙塔尔是一群统治沙塔斯城的强大纳鲁人的组织。在奥尔多和占星者的帮助下，他们正在领导针对伊利丹和燃烧军团的战斗。" },
  [936] = { "沙塔斯城" },
  [937] = { "森林巨魔" },
  [938] = { "欧麦尼" },
  [940] = { "洛萨之子" },
  [941] = { "玛格汉", "这群隐居的棕皮兽人逃脱了恶魔的腐蚀，并在天崩地裂的外域中保持了古老的传统。" },
  [942] = { "塞纳里奥远征队", "塞纳里奥议会派往外域研究生态的探险队。在黑暗之门开启后，远征队迅速壮大，并获得了自治权。" },
  [943] = { "邪兽人" },
  [944] = { "邪兽人幽灵" },
  [945] = { "洛萨之子" },
  [946] = { "荣耀堡", "这座前哨基地坐落在地狱火半岛上，由第一批深入德拉诺的联盟精英部队“洛萨之子”的残余力量坚守。现在他们得到了来自暴风城和铁炉堡的支援。" },
  [947] = { "萨尔玛", "由萨尔派出的远征军在地狱火半岛建立的要塞。萨尔玛是部落在外域的大部分行动的根据地。" },
  [955] = { "破碎者" },
  [956] = { "复仇军" },
  [957] = { "土元素" },
  [958] = { "打架机器人" },
  [959] = { "好演员" },
  [960] = { "坏演员" },
  [961] = { "止松熊怪" },
  [962] = { "疯狂的枭兽" },
  [963] = { "联盟棋子" },
  [964] = { "部落棋子" },
  [967] = { "紫罗兰之眼", "一个由肯瑞托为了调查麦迪文和监视他的活动而建立的秘密组织。" },
  [968] = { "炎鹰" },
  [969] = { "阿古斯之手" },
  [970] = { "孢子村", "生活在外域的孢子人是一个非常温和的种族。他们的家园就坐落在赞加沼泽南部的沼泽地中。" },
  [971] = { "真菌巨人" },
  [972] = { "孢子蝠" },
  [975] = { "虚空畸能" },
  [976] = { "海加尔防御者" },
  [977] = { "海加尔入侵者" },
  [978] = { "库雷尼", "在德莱尼语中意为“得到救赎”。这些从各种奴役和控制中逃出来的破碎者在纳格兰建立了自己的家园，寻找自己真正的命运。" },
  [979] = { "大地之环，旧世界" },
  [980] = { "燃烧的远征" },
  [981] = { "鸦人" },
  [982] = { "赞加沼泽军旗（联盟）" },
  [983] = { "赞加沼泽军旗（部落）" },
  [984] = { "赞加沼泽军旗（中立）" },
  [985] = { "时光之穴 - 萨尔" },
  [986] = { "时光之穴 - 敦霍尔德" },
  [987] = { "时光之穴 - 南海镇卫兵" },
  [988] = { "暗影议会" },
  [989] = { "时光守护者", "这些由诺兹多姆亲自挑选的青铜龙无时无刻不在监视着时光之穴。" },
  [990] = { "流沙之鳞", "隶属于青铜龙军团的秘密组织，由诺兹多姆最亲密的伴侣索莉多米领导。" },
  [999] = { "法力生物" },
  [1000] = { "卡德加的仆从" },
  [1001] = { "刀塔氏族" },
  [1002] = { "复仇军" },
  [1003] = { "维序派" },
  [1010] = { "伊利丹的仆从" },
  [1011] = { "贫民窟", "来自各个地方、各个种族的避难者在沙塔斯城的聚集地。在贫民窟中，善行善举总是会很快传遍所有人的耳朵。" },
  [1012] = { "灰舌死誓者", "来自破碎者灰舌部族的精英勇士，表面上与伊利丹结盟。这些勇士是阿卡玛最信任的部下，并参与了他的秘密计划。" },
  [1015] = { "灵翼之龙", "这种罕见的龙是死亡之翼的后代，受到原始的虚空能量影响后发生了变异。现在，他们正在努力摆脱死亡之翼的血脉带来的阴影，找寻自己的命运。" },
  [1016] = { "拜龙教" },
  [1017] = { "树人" },
  [1023] = { "阿萨洛斯" },
  [1024] = { "剥石者" },
  [1025] = { "剥石者猎手" },
  [1026] = { "影月之魂" },
  [1027] = { "军团联络器" },
  [1028] = { "乌鸦林古树" },
  [1031] = { "沙塔尔天空卫队", "一支由沙塔斯城建立的空中武装力量，职责是应对潜伏在外域天空中的威胁。" },
  [1032] = { "52区" },
  [1033] = { "玛维" },
  [1034] = { "斯克提斯阴影鸦人" },
  [1035] = { "斯克提斯鸦人" },
  [1036] = { "龙喉之敌" },
  [1037] = { "联盟先遣军", "联盟派往诺森德的多支部队的统称，由无畏远征军领导。同时也包括一些非军事组织，如探险者协会。" },
  [1038] = { "奥格瑞拉", "聪明而开化的奥格瑞拉食人魔居住在刀锋山的西部区域，那里富产的埃匹希斯水晶使得他们的智商远远超越了其他野蛮的同类。" },
  [1039] = { "掠食者" },
  [1041] = { "狂鱼" },
  [1042] = { "天空卫队之敌" },
  [1043] = { "臭鼬" },
  [1044] = { "塞拉摩叛逃者" },
  [1045] = { "维库人" },
  [1046] = { "北海海盗" },
  [1047] = { "海象人" },
  [1049] = { "阿曼尼巨魔" },
  [1050] = { "无畏远征军", "联盟在诺森德的主力部队，由瓦里安·乌瑞恩国王统领，对抗天灾军团。" },
  [1052] = { "部落先遣军", "部落派往诺森德的多支部队的统称，由战歌远征军充当先头部队。" },
  [1061] = { "维库人" },
  [1062] = { "维库角斗士" },
  [1064] = { "牦牛人", "这些坚强的牦牛人是牛头人的同类，在部落远征诺森德的战役中，他们成为了具有重要价值的斥候。" },
  [1067] = { "复仇之手", "这支由希尔瓦娜斯·风行者派遣的被遗忘者势力想要在诺森德散播他们最新研制成功的瘟疫病菌，以此来向阿尔萨斯复仇。" },
  [1068] = { "探险者协会", "这个组织致力于通过发掘泰坦遗留下来的古器追寻矮人种族的起源。最近他们来到诺森德的多处古迹进行研究。" },
  [1073] = { "卡鲁亚克", "海象人是坚韧而和平的种族，通过捕鲸和捕鱼谋生。他们的家园最近正在遭受凶猛的攻击，急需来自外界的援手。" },
  [1076] = { "铁矮人" },
  [1077] = { "破碎残阳", "沙塔斯城的精锐部队，目标是向太阳之井的凯尔萨斯王子发动最终的攻势。" },
  [1078] = { "战斗宠物" },
  [1079] = { "冬鳍鱼人" },
  [1085] = { "战歌远征军", "部落的主力部队由加尔鲁什·地狱咆哮率领，向盘踞在诺森德的阿尔萨斯和天灾军团发起挑战。" },
  [1087] = { "节日怪物" },
  [1090] = { "肯瑞托", "统治达拉然的法师和大法师们。由于蓝龙军团和亡灵天灾造成的威胁，他们将整座城市传送到了诺森德的腹地。" },
  [1091] = { "龙眠联军", "由于蓝龙军团粗暴地干涉凡人种族使用魔法的权利，其余的龙族不得不联合在红龙军团旗下，与这些狂乱的同胞抗衡。" },
  [1092] = { "艾卓-尼鲁布" },
  [1094] = { "银色盟约", "这支高等精灵中的精锐部队拒绝让血精灵进入肯瑞托。他们联合在温蕾萨·风行者的旗帜下，与诺森德的联盟军队并肩作战。" },
  [1097] = { "巫妖王之怒" },
  [1098] = { "黑锋骑士团", "在脱离了巫妖王的控制之后，这些曾经效命于他的死亡骑士联合起来，在大领主达里安·莫格莱尼的领导下对抗巫妖王。" },
  [1104] = { "狂心氏族", "这群凶猛的狼獾人被天灾军团追杀，偶然来到了索拉查盆地，遂决定在此安家。由于极富攻击性，他们与被称为神谕者的鳄鱼人部族成水火之势。" },
  [1105] = { "神谕者", "索拉查盆地的鳄鱼人将自己视为该区域中存留的泰坦科技的守护者（虽然他们基本不了解这种科技）。目前他们正在与狼獾人进行着不断激化的领土战争。" },
  [1106] = { "银色北伐军", "提里奥·弗丁领导的银色北伐军是由白银之手骑士团和银色黎明重组而成的，他们的目标是击溃巫妖王的军队。" },
  [1111] = { "弗蕾亚" },
  [1117] = { "索拉查盆地" },
  [1118] = { "经典旧世" },
  [1119] = { "霍迪尔之子", "这支风暴峭壁的冰霜巨人部族非常好战，他们定居在丹尼芬雷。" },
  [1120] = { "铁巨人" },
  [1121] = { "冰霜维库人" },
  [1122] = { "风暴峭壁土灵" },
  [1124] = { "夺日者", "在大法师艾萨斯·夺日者的努力下，一贯被达拉然据之门外的部落也获准进入这座城市。他的追随者保卫着以他的名字命名的夺日者圣殿。" },
  [1125] = { "海德比武会" },
  [1126] = { "霜脉矮人", "这个神秘的冰霜矮人种族定居在风暴峭壁。他们最近与探险者协会成为了朋友，并且欢迎联盟的成员造访他们的家园。" },
  [1128] = { "暮光之锤" },
  [1129] = { "黑木熊怪" },
  [1130] = { "黑海岸雄鹿" },
  [1131] = { "黑海岸巨熊" },
  [1132] = { "黑海岸月夜猛虎" },
  [1133] = { "锈水财阀", "由无情的贸易巨子加里维克斯控制的锈水财阀是科赞岛上最强大的贸易公司。他们的总部坐落在锈水码头，整片南海的贸易都被他们所掌控。" },
  [1134] = { "吉尔尼斯", "吉尔尼斯是一个幸存者的国度。当他们最后的人性也被剥去后，吉尔尼斯面临着来自内部的全新威胁。" },
  [1135] = { "大地之环", "艾泽拉斯最强大的萨满祭司都聚集到了一起，期望能够维持这个世界各股元素力量之间的平衡。在这场大灾变中，他们正竭力修复死亡之翼的来临对世界造成的伤害。" },
  [1136] = { "塔奎林声望转换" },
  [1137] = { "霜刃豹声望转换" },
  [1138] = { "大灾变，新的中立声望" },
  [1142] = { "玛格拉姆遗族" },
  [1143] = { "吉尔吉斯之子" },
  [1145] = { "憎世者" },
  [1152] = { "地精（玩家）" },
  [1153] = { "狼人（玩家）" },
  [1154] = { "银色盟约声望转换" },
  [1155] = { "夺日者声望转换" },
  [1156] = { "灰烬审判军", "在提里奥·弗丁与达里安·莫格莱尼的共同协议下，银色北伐军与黑锋骑士团决定暂时放下分歧、统一战线，合力攻入冰冠堡垒，击败巫妖王。" },
  [1157] = { "俾格米人" },
  [1158] = { "海加尔守护者", "圣山海加尔面临着毁灭的威胁，塞纳里奥议会集结了最强大的成员，与他们的翡翠绿龙盟友一同抵御着拉格纳罗斯和暮光之锤的入侵。" },
  [1161] = { "恐怖图腾" },
  [1162] = { "大地的裂变" },
  [1168] = { "公会", "公会声望代表了你在公会中的个人地位，购买公会奖励时需要达到与之对应的声望。公会声望会在你获得公会经验值时自动获得。" },
  [1169] = { "公会" },
  [1171] = { "塞拉赞恩", "塞拉赞恩和她的石领主子嗣们统治着土元素位面深岩之洲。在见证了死亡之翼及其追随者对她的国度造成的伤害后，塞拉赞恩对所有外来者都充满了敌意。" },
  [1172] = { "龙喉氏族", "这支狂放不羁的兽人氏族曾经在死亡之翼的授意下奴役了红龙军团和阿莱克丝塔萨。如今龙喉氏族的数量和实力都已不如往昔，他们在暮光高地上建立了家园。" },
  [1173] = { "拉穆卡恒", "拉穆卡恒的猫形子民是奥丹姆守护者托维尔一族的后裔。尽管他们失去了石头的身体，但保护泰坦秘密的使命仍然留在了他们一成不变的传统中。" },
  [1174] = { "蛮锤部族", "蛮锤部族以他们近乎鲁莽的勇气和出类拔萃的狮鹫骑战技艺而闻名。因为黑铁矮人的诅咒，他们失去了在格瑞姆巴托的家园。在那之后，蛮锤矮人们分散地定居在暮光高地上。" },
  [1177] = { "巴拉丁典狱官", "这支曾经由雷吉纳德·巴拉丁二世公爵率领的精锐之师和海岛要塞托尔巴拉德有着深厚的历史渊源。他们加入了联盟军队，旨在击退部落入侵者并捍卫这座极具战略意义的岛屿。" },
  [1178] = { "地狱咆哮近卫军", "地狱咆哮近卫军是部落的一支精英部队，由最骁勇善战的老兵编制而成。加尔鲁什亲自选拔了这些战士，并命令他们夺取托尔巴拉德。只许成功，不许失败。" },
  [1179] = { "软泥怪" },
  [1181] = { "友善，新" },
  [1204] = { "海加尔复仇者", "火元素领主带来的毁灭激怒了塞纳里奥议会。他们主动出击，直捣拉格纳罗斯在火焰之地的巢穴。" },
  [1216] = { "尚喜武院", "备受尊重的尚喜大师教导过无数渴望冒险的熊猫人英雄，尚喜武院的历史也可以追溯至三代人之前。" },
  [1228] = { "森林猢狲", "一支活泼、暴躁而短命的猴族。" },
  [1242] = { "珠鳍锦鱼人", "一支内敛而守序的鱼形人种族。" },
  [1243] = { "猢狲", "高贵而活泼，以原始部落方式生存的猴族。" },
  [1245] = { "熊猫人之谜" },
  [1249] = { "玩家，内容更新4中立" },
  [1252] = { "煞", "这片土地的邪恶之魂。" },
  [1253] = { "东方之寺的守护者" },
  [1265] = { "辛德拉", "一群居住在厄运之槌的精灵后裔，他们仍然具有着相当渊博的智慧与学识，并保守着一些伟大的秘密。" },
  [1268] = { "魔古族", "魔古族曾是古代潘达利亚的统治者。如今他们仇视所有篡夺这片土地的下等种族，特别是那些自命不凡的熊猫人。" },
  [1269] = { "金莲教", "这支神秘的熊猫人教派意图一劳永逸地解决魔古族带来的麻烦。" },
  [1270] = { "影踪派", "这个神秘莫测的熊猫人门派守护着潘达利亚的天神寺庙。" },
  [1271] = { "云端翔龙骑士团", "东方之寺的守护者" },
  [1272] = { "阡陌客", "阡陌客是一个由热爱和平与劳作的熊猫人结成的农业组织。他们终日辛勤耕作，只为满足熊猫人一族对美食的终极追求。" },
  [1273] = { "醉鬼贾古", "贾古很容易找到——只要去看看风暴烈酒酿造厂出品的最廉价的酒桶底部就行了。" },
  [1275] = { "艾拉", "艾拉渴望成为一名伟大的酒仙，但她还有很多路要走！" },
  [1276] = { "老农山掌", "老农山掌是四邻八乡最有经验的养鸡专业户。" },
  [1277] = { "吱吱", "如果你有关于绵羊的问题，吱吱一定能帮你解答。" },
  [1278] = { "阿烁", "作为一个壮实、自豪的农场保卫者，阿烁总会在你需要一个强壮的打手时出现。" },
  [1279] = { "郝瀚·泥爪", "作为阡陌客的可敬领袖，郝瀚·泥爪责任重大。" },
  [1280] = { "迪娜·泥爪", "迪娜·泥爪最喜欢生活中那些精美的物品。" },
  [1281] = { "吉娜·泥爪", "经营半山市集使吉娜·泥爪变成了一位强势的女性！" },
  [1282] = { "玉儿·采苇", "相比其他健忘的镇民，玉儿·采苇更了解这片土地的历史。" },
  [1283] = { "农夫老方", "农夫老方家种的蔬菜可是汇风岭一绝！" },
  [1286] = { "朱鹤守护者" },
  [1302] = { "垂钓翁", "授人以鱼不如授人以渔，这群名为垂钓翁的熊猫人不光想着填饱族人的肚子，还希望能够提高自己的钓鱼本领。" },
  [1336] = { "螳螂妖虫群", "横扫螳螂高原和恐惧废土的恐怖掠食虫群，所过之处无不是一片狼藉。" },
  [1337] = { "卡拉克西", "令整支螳螂妖虫群发疯的堕落之源并没有影响到这些螳螂妖长者。他们希望与潘达利亚的其他种族合作，从而找到令族群和女皇恢复如初的方法。" },
  [1338] = { "格尔桑魔古氏族" },
  [1339] = { "哈飒克魔古氏族" },
  [1340] = { "卡尔格魔古氏族" },
  [1341] = { "至尊天神", "勇敢的熊猫人为了保卫潘达利亚的四方神寺而与邪恶的煞战斗。" },
  [1345] = { "游学者", "作为潘达利亚秘密的守护者，这些勇敢的学者周游大陆，希望能以史为鉴，继往开来。" },
  [1351] = { "酒仙会", "这些高贵的熊猫人守护着世代相传的酿酒秘诀，为了酿造出烈性美酒而甘冒奇险。" },
  [1352] = { "火金派熊猫人", "勇敢无畏的季·火掌领导着火金派熊猫人。他们风风火火，敢作敢为，为贯彻自己的信念而战。" },
  [1353] = { "土水派熊猫人", "沉静稳重的艾莎·云歌领导着土水派熊猫人。他们深思熟虑，三思而行，一切行动都遵循理性。" },
  [1358] = { "纳特·帕格", "纳特是全世界最负盛名的钓鱼大师与美酒爱好者，在他暴躁易怒的外表下藏着一颗好为人师的心。" },
  [1359] = { "黑王子", "黑王子拉希奥是黑龙族群的最后一员。传说他对忠诚效命者的报酬十分丰厚。" },
  [1371] = { "坡东村" },
  [1372] = { "蜜露村" },
  [1374] = { "搏击竞技场（第1赛季）", "在潘达利亚战役期间，部落搏击俱乐部的第一赛季拉开了帷幕。" },
  [1375] = { "统御先锋军", "潘达利亚的部落部队，驻扎在卡桑琅丛林的统御岗哨。" },
  [1376] = { "神盾守备军", "潘达利亚的联盟部队，驻扎在卡桑琅丛林的雄狮港。" },
  [1387] = { "肯瑞托远征军", "被吉安娜的怒火点燃，肯瑞托远征军誓要夺取雷神岛，捍卫联盟的荣耀！" },
  [1388] = { "夺日者先锋军", "被赶离达拉然后，夺日者先锋军致力于在雷神岛的废墟间寻找强大的魔古族神器，万一部落分崩离析，好将未来掌握在自己手中。" },
  [1416] = { "阿卡玛的信任", "在见证了伊利丹的堕落后，阿卡玛对术士充满了猜忌。而大灾变之后，术士们又对黑暗神殿展开了入侵。" },
  [1419] = { "比兹莫搏击俱乐部（第1赛季）", "在潘达利亚战役期间，联盟搏击俱乐部的第一赛季拉开了帷幕。" },
  [1435] = { "影踪突袭营", "这些勇敢的影踪派成员们深入雷电王座，全力以赴遏制暗藏其中的邪恶势力，也为自己千百年来饱受雷电之王奴役的遭遇伸张正义。" },
  [1440] = { "暗矛起义军", "沃金已经公开宣布反抗加尔鲁什·地狱咆哮。在部落和联盟军队的帮助下，他正在收集资源，准备对奥格瑞玛发动总攻。" },
  [1443] = { "库卡隆" },
  [1444] = { "德拉诺之王" },
  [1445] = { "霜狼兽人", "霜火岭的霜狼兽人是一群紧密团结在一起的凶猛战士。他们能很好地适应德拉诺残酷的环境。" },
  [1447] = { "暗矛巨魔" },
  [1457] = { "蕨人" },
  [1483] = { "食蕨人" },
  [1491] = { "时光旅行者", "时光旅行者保卫着时间流，不让那些因青铜龙军团的覆灭而蠢蠢欲动的人有机可乘；他们主要由冒险者和学者组成，大多是原时光守护者的成员。" },
  [1492] = { "皇帝少昊", "少昊是逝去已久的熊猫人皇帝，是一位值得敬重的人物。" },
  [1496] = { "霜火食人魔", "霜火食人魔没什么爱好，就是喜欢吵架。" },
  [1500] = { "血红幽灵", "你被斡耳朵的力量腐蚀了。被怒火冲昏头脑的你将对盟友和敌人进行无差别攻击。" },
  [1508] = { "影月兽人" },
  [1509] = { "白鬼" },
  [1514] = { "鲁克玛信徒", "作为恐怖之神鲁克玛的崇拜者，这些邪恶的暴徒试图用敌人的鲜血染红这个世界。" },
  [1515] = { "鸦人流亡者", "在黑暗中挣扎的鸦人流亡者在苦苦追寻着光明的未来。" },
  [1520] = { "影月流亡者" },
  [1521] = { "暗影议会" },
  [1591] = { "德莱尼，德拉诺" },
  [1617] = { "原兽" },
  [1618] = { "毁灭者" },
  [1623] = { "钢铁部落", "由德拉诺的众多兽人氏族勉强联合而成的脆弱联盟，由格罗玛什·地狱咆哮领导。" },
  [1665] = { "萨格雷", "一群扭曲并效忠暗影议会的德莱尼，为了追求力量牺牲了许多东西。" },
  [1674] = { "德拉诺孢子" },
  [1679] = { "阿德瓦克讨伐军" },
  [1680] = { "悬槌堡", "悬槌食人魔喜欢穿宽外袍，观看角斗士比赛。" },
  [1681] = { "沃金之矛", "部落在阿什兰的部队，驻扎在战争之矛。" },
  [1682] = { "乌瑞恩先锋军", "联盟在阿什兰的部队，驻扎在暴风之盾。" },
  [1687] = { "戈尔隆德鬣蜥人" },
  [1690] = { "搏击竞技场（第2赛季）", "德拉诺战役期间的部落搏击俱乐部第二赛季活动。" },
  [1691] = { "比兹莫搏击俱乐部（第2赛季）", "德拉诺战役期间的联盟搏击俱乐部第二赛季活动。" },
  [1708] = { "嘲颅兽人", "嘲颅氏族的家园位于德拉诺最蛮荒的边界。他们会对来自各方的毁灭威胁报以疯狂的癫笑。" },
  [1710] = { "沙塔尔防御者", "努力想要夺回主城的沙塔斯城防御者，但却遭到来自内部的背叛。" },
  [1711] = { "热砂保护协会", "热砂保护协会的地精们致力于将珍贵的遗物从纳格兰的食人魔手中解放出来。毋庸置疑，他们必然是怀着崇高的目标——把遗物卖出最高的价钱——来做这件事的。" },
  [1731] = { "主教议会", "在五位强大的大主教率领下，德拉诺的德莱尼在这个蛮荒的世界中欣欣向荣。" },
  [1732] = { "热砂港德拉诺探险队", "德拉诺有着无限的商机和极其有限的竞争。" },
  [1733] = { "德尔瓦·铁拳", "你的私人保镖，驻扎在你的兵营里。你可以通过邀请德尔瓦一起战斗，与他建立起友谊。" },
  [1735] = { "要塞保镖", "驻扎在你兵营中的保镖。" },
  [1736] = { "托莫克", "你的私人保镖，驻扎在你的兵营里。你可以通过邀请托莫克一起战斗，与他建立起友谊。" },
  [1737] = { "鸦爪祭司伊沙尔", "你的私人保镖，驻扎在你的兵营里。你可以通过邀请伊沙尔一起战斗，与他建立起友谊。" },
  [1738] = { "防御者艾萝娜", "你的私人保镖，驻扎在你的兵营里。你可以通过邀请艾萝娜一起战斗，与她建立起友谊。" },
  [1739] = { "薇薇安", "你的私人保镖，驻扎在你的兵营里。你可以通过邀请薇薇安一起战斗，与她建立起友谊。" },
  [1740] = { "艾达·晨光", "你的私人保镖，驻扎在你的兵营里。你可以通过邀请艾达一起战斗，与她建立起友谊。" },
  [1741] = { "利奥拉", "你的私人保镖，驻扎在你的兵营里。你可以通过邀请利奥拉一起战斗，与他建立起友谊。" },
  [1746] = { "纳格兰戈隆" },
  [1747] = { "角斗场宝藏" },
  [1760] = { "悬槌角斗士", "悬槌食人魔喜欢穿宽外袍，观看角斗士比赛。" },
  [1786] = { "燃烧军团入侵者", "来自未知之地的恶魔，有着无与伦比的力量。" },
  [1815] = { "吉尔尼斯幸存者" },
  [1828] = { "高岭部族", "高岭部族的人口已经逐年减少，随着卓格巴尔的威胁加剧，他们需要寻找新的盟友来拯救他们的家园。" },
  [1833] = { "无冕者", "如果你非要问的话，那你已经是个死人了。" },
  [1834] = { "军团再临" },
  [1847] = { "先知之手", "伊瑞尔集结了幸存下来的大主教们，并以维伦的名义发动了攻势。当前他们正试图在塔纳安丛林建立据点，誓要将古尔丹的阴谋彻底粉碎。" },
  [1848] = { "沃金之锋", "要想守护艾泽拉斯，就必须在德拉诺取得决定性胜利。为此，部落酋长沃金召集了麾下最最精锐的勇士在塔纳安丛林建立据点，只为打倒古尔丹等邪恶势力。" },
  [1849] = { "觉醒教派", "作为一场残酷内战的幸存者，这些四面受敌的鸦人希望找回埃匹希斯神器是帮助他们和平重建鸦人文明的关键。" },
  [1850] = { "刃牙追猎者", "危机四伏的塔纳安丛林吸引来艾泽拉斯和德拉诺出类拔萃的猎手。想要击败塔纳安的野兽，你就得比他们更野。" },
  [1859] = { "堕夜精灵", "这些被放逐的夜之子精灵由于被切断了和暗夜井的联系，饱受戒断魔瘾的痛苦。他们反对同胞与燃烧军团结盟，并为某种救赎而战。" },
  [1860] = { "魔瘾（塔莉萨）", "首席奥术师塔莉萨" },
  [1861] = { "魔瘾（希尔格林）废弃", "废弃" },
  [1862] = { "魔瘾（欧库勒斯）", "首席传送师欧库勒斯" },
  [1883] = { "织梦者", "德鲁伊和他们在瓦尔莎拉的盟友从不可考的年代起，就一直守护着翡翠梦境。" },
  [1888] = { "贾德维克维库人" },
  [1894] = { "守望者", "自从燃烧军团在古尔丹的帮助下攻破守望者地窟后，剩下的少数守望者就决心重建她们的监狱并追捕那些趁乱逃跑的恐怖野兽。" },
  [1899] = { "月之守卫", "占位符" },
  [1900] = { "法罗迪斯宫廷", "由幽灵组成的法罗迪斯宫廷及它的盟友们正在阿苏纳被诅咒的岛屿上持续抗击入侵者。" },
  [1905] = { "梦境林地德鲁伊" },
  [1910] = { "卓格巴尔" },
  [1911] = { "克瓦迪尔幽魂" },
  [1912] = { "克瓦迪尔" },
  [1913] = { "夜之子" },
  [1914] = { "枯法者" },
  [1919] = { "魔瘾（瓦尔托伊）", "奥术师瓦尔托伊" },
  [1920] = { "月之守卫" },
  [1947] = { "伊利达雷", "发誓要不惜一切代价对抗燃烧军团的精灵。" },
  [1948] = { "瓦拉加尔", "他们是被奥丁选中的战士，发誓在生前及死后都效忠于他。" },
  [1953] = { "梦魇" },
  [1962] = { "夜之子平民" },
  [1975] = { "咒法师马戈斯", "马戈斯曾是一名肯瑞托学徒，他通过钓鱼来舒缓生活的压力。" },
  [1984] = { "急救队", "欧莉萨拉和安吉莉克住在浮空城达拉然。她们在这里救死扶伤，治病救人。她们还向需要医疗补给的旅行者出售物品。" },
  [1989] = { "月之守卫" },
  [2010] = { "搏击竞技场（第3赛季）", "在破碎群岛战役期间，部落搏击俱乐部展开了第三赛季的活动。" },
  [2011] = { "比兹莫搏击俱乐部（第3赛季）", "在破碎群岛战役期间，联盟搏击俱乐部展开了第三赛季的活动。" },
  [2012] = { "夜之子起义军" },
  [2018] = { "复仇之爪", "半神艾维娜的盟友，破碎群岛所有有翼生物的守护者。" },
  [2040] = { "复仇之爪", "半神艾维娜的盟友，破碎群岛所有有翼生物的守护者。" },
  [2045] = { "抗魔联军", "各大势力的联军，致力于击败萨格拉斯之墓和破碎海滩的燃烧军团。" },
  [2085] = { "高岭部族（典范）", "高岭部族的人口已经逐年减少，随着卓格巴尔的威胁加剧，他们需要寻找新的盟友来拯救他们的家园。" },
  [2086] = { "瓦拉加尔（典范）", "他们是被奥丁选中的战士，发誓在生前及死后都效忠于他。" },
  [2087] = { "法罗迪斯宫廷（典范）", "由幽灵组成的法罗迪斯宫廷及它的盟友们正在阿苏纳被诅咒的岛屿上持续抗击入侵者。" },
  [2088] = { "织梦者（典范）", "德鲁伊和他们在瓦尔莎拉的盟友从不可考的年代起，就一直守护着翡翠梦境。" },
  [2089] = { "堕夜精灵（典范）", "这些被放逐的夜之子精灵由于被切断了和暗夜井的联系，饱受戒断魔瘾的痛苦。他们反对同胞与燃烧军团结盟，并为某种救赎而战。" },
  [2090] = { "守望者（典范）", "自从燃烧军团在古尔丹的帮助下攻破守望者地窟后，剩下的少数守望者就决心重建她们的监狱并追捕那些趁乱逃跑的恐怖野兽。" },
  [2091] = { "抗魔联军（典范）", "各大势力的联军，致力于击败萨格拉斯之墓和破碎海滩的燃烧军团。" },
  [2097] = { "“活水”伊丽西娅", "阿苏纳的皇家池塘古老的守护者。" },
  [2098] = { "守护者蕾娜", "瓦尔莎拉的护渔人。" },
  [2099] = { "阿库勒·河角", "河流和鱼类大师。" },
  [2100] = { "科尔宾", "有着一双明亮睿智眼睛的渡鸦，喜欢鱼。" },
  [2101] = { "莎乐丝", "住在瀑布旁的神秘枯法者。" },
  [2102] = { "英帕斯", "被人从远方召唤的英帕斯正在收集贝壳，希望能制造出一座“魔法传送门”返回家乡。" },
  [2103] = { "赞达拉帝国", "赞达拉巨魔统治着艾泽拉斯最古老的帝国，这些强大的巨魔会与令人敬畏的洛阿神灵做交易，换取他们的力量，赞达拉的海军在无尽之海上也是所向披靡。" },
  [2104] = { "争霸艾泽拉斯" },
  [2105] = { "纳兹曼尼" },
  [2111] = { "赞达拉恐龙" },
  [2120] = { "库尔提拉斯 - 提拉加德", "岛国库尔提拉斯盛产艾泽拉斯最一流的水手。" },
  [2121] = { "无尽之海水手", "无尽之海上无拘无束的人，他们只对自己的船队效忠。" },
  [2122] = { "铁潮突袭队", "残忍的海盗团伙，以提拉加德海峡的自由镇为据点。" },
  [2135] = { "克罗米", "克罗诺姆（简称克罗米）是一头活跃、亲切的青铜龙。拉近你与她之间关系将增强她在场景战役“克罗米之死”中的力量。" },
  [2155] = { "鲜血巨魔" },
  [2156] = { "塔兰吉远征队", "塔兰吉公主和他的盟友正努力保护赞达拉不受鲜血巨魔的侵扰。" },
  [2157] = { "荣耀战团", "部落大军中的特种部队，专注于破坏联盟在库尔提拉斯的行动。" },
  [2158] = { "沃顿奈", "沃顿奈是流亡者和拾荒者的组织，他们依靠对沙漠的了解逐步发展壮大，而其他人只能在这里枯萎凋亡。" },
  [2159] = { "第七军团", "联盟军队中的精英部队，目前专注于破坏部落在赞达拉的行动。" },
  [2160] = { "普罗德摩尔海军部", "普罗德摩尔家族是人中龙凤，执掌着艾泽拉斯最精良的海军，足以号令大海。数十年来，他们在权力中心伯拉勒斯领导着库尔提拉斯。" },
  [2161] = { "灰烬骑士团", "灰烬骑士团是个古老的库尔提拉斯组织，它的重生是为了对抗女巫的威胁。骑士团利用他们所获得的知识指引他们的利刃，以此英勇战斗。" },
  [2162] = { "风暴之末", "风暴之末是农民、匠人、士兵和神秘的海贤们的家，他们希望夺回斯托颂谷地，并且确立自己在库尔提拉斯的地位。" },
  [2163] = { "始祖龟求知者", "始祖龟求知者周游世界并利用他们的巨大财富来分类并保存禁忌的知识。" },
  [2164] = { "艾泽拉斯的勇士", "萨格拉斯的燃烧之刃对艾泽拉斯造成了巨大的创伤，由麦格尼·铜须招募而来的艾泽拉斯的勇士正在努力治愈这些伤口，以拯救这个濒死的世界。" },
  [2165] = { "圣光军团", "阿古斯陷落后，德莱尼精英战士追随始祖纳鲁泽拉跨越宇宙，打响了旨在消灭燃烧军团的永恒之战。从那时起，燃烧的远征的其他幸存者也加入了光铸者的行列。" },
  [2166] = { "圣光军团（典范）" },
  [2167] = { "阿古斯防卫军（典范）" },
  [2170] = { "阿古斯防卫军", "虽然有许多人都在燃烧军团征服阿古斯时奋起抗争，但并不是所有人都成功逃离了。而今在新的友军的鼓舞下，这些难民和流亡者已经联合起来，为夺回家园而战。" },
  [2185] = { "水鼠帮", "不同寻常的“混血”种族组成的队伍，以提拉加德海峡的自由镇为据点。" },
  [2186] = { "黑齿帮", "一队擅长混战的打手，从不畏惧战斗。是提拉加德海峡的自由镇上的诸多海盗团体之一。" },
  [2187] = { "破浪海盗", "一队狡猾的雇佣兵和强盗，只为出价最高的人卖命。没有接活儿时，他们会停靠在提拉加德海峡的自由镇的港口。" },
  [2192] = { "艾什凡贸易公司", "运输和制造业公司，总部在伯拉勒斯，库尔提拉斯的首都。这里有传言说，这个宏伟的公司其实是一个可怕的犯罪帝国的门面。" },
  [2227] = { "野兽 - 蜜蜂" },
  [2228] = { "野兽 - 雪怪" },
  [2233] = { "恐龙训练 - 翼手龙" },
  [2258] = { "雪怪" },
  [2259] = { "蜜蜂" },
  [2264] = { "库尔提拉斯 - 德鲁斯瓦", "岛国库尔提拉斯盛产艾泽拉斯最一流的水手。" },
  [2265] = { "库尔提拉斯 - 斯托颂", "岛国库尔提拉斯盛产艾泽拉斯最一流的水手。" },
  [2370] = { "恐龙训练 - 恐角龙" },
  [2371] = { "比兹莫搏击俱乐部（第4赛季）", "联盟搏击俱乐部第四季发生在库尔提拉斯战役期间。" },
  [2372] = { "搏击竞技场（第4赛季）", "部落搏击俱乐部第四季发生在库尔提拉斯战役期间。" },
  [2373] = { "破镣者", "这些难民一直受到纳迦的压迫，于是他们联合起来，想要反抗，并重获自由。" },
  [2374] = { "破镣者（典范）", "这些难民一直受到纳迦的压迫，于是他们联合起来，想要反抗，并重获自由。" },
  [2375] = { "猎人阿卡纳", "猎人阿卡纳是位久经沙场的老猎人，拥有了不起的生存技巧。" },
  [2376] = { "先知奥利", "先知奥利是位睿智而强大的萨满，拥有号令元素的力量。" },
  [2377] = { "剑客伊诺瓦里", "剑客伊诺瓦里是位老练的战士，他赢得了剑鱼人的尊敬。" },
  [2378] = { "赞达拉帝国（典范）", "赞达拉巨魔统治着艾泽拉斯最古老的帝国，这些强大的巨魔会与令人敬畏的洛阿神灵做交易，换取他们的力量，赞达拉的海军在无尽之海上也是所向披靡。" },
  [2379] = { "普罗德摩尔海军部（典范）", "普罗德摩尔家族是人中龙凤，执掌着艾泽拉斯最精良的海军，足以号令大海。数十年来，他们在权力中心伯拉勒斯领导着库尔提拉斯。" },
  [2380] = { "塔兰吉远征队（典范）", "塔兰吉公主和他的盟友正努力保护赞达拉不受鲜血巨魔的侵扰。" },
  [2381] = { "风暴之末（典范）", "风暴之末是农民、匠人、士兵和神秘的海贤们的家，他们希望夺回斯托颂谷地，并且确立自己在库尔提拉斯的地位。" },
  [2382] = { "沃顿奈（典范）", "沃顿奈是流亡者和拾荒者的组织，他们依靠对沙漠的了解逐步发展壮大，而其他人只能在这里枯萎凋亡。" },
  [2383] = { "灰烬骑士团（典范）", "灰烬骑士团是个古老的库尔提拉斯组织，它的重生是为了对抗女巫的威胁。骑士团利用他们所获得的知识指引他们的利刃，以此英勇战斗。" },
  [2384] = { "第七军团（典范）", "联盟军队中的精英部队，目前专注于破坏部落在赞达拉的行动。" },
  [2385] = { "荣耀战团（典范）", "部落大军中的特种部队，专注于破坏联盟在库尔提拉斯的行动。" },
  [2386] = { "艾泽拉斯的勇士（典范）", "萨格拉斯的燃烧之刃对艾泽拉斯造成了巨大的创伤，由麦格尼·铜须招募而来的艾泽拉斯的勇士正在努力治愈这些伤口，以拯救这个濒死的世界。" },
  [2387] = { "始祖龟求知者（典范）", "始祖龟求知者周游世界并利用他们的巨大财富来分类并保存禁忌的知识。" },
  [2388] = { "鲍恩·分鳃", "部落阵营1" },
  [2389] = { "奈莉·锐鳍", "部落阵营2" },
  [2390] = { "维姆·盐心", "部落阵营3" },
  [2391] = { "锈栓抵抗军", "锈栓抵抗军战斗在第一线，想要反抗麦卡贡国王，阻止他的邪恶计划。" },
  [2392] = { "锈栓抵抗军（典范）", "锈栓抵抗军战斗在第一线，想要反抗麦卡贡国王，阻止他的邪恶计划。" },
  [2394] = { "寄居蟹" },
  [2395] = { "蜜背蜂群", "一种特别的蜜蜂，以其超大的体形而闻名。虽然它们最近才来到斯托颂谷地，但它们的存在已经迅速在冒险者和昆虫爱好者当中流传开来。" },
  [2396] = { "蜜背工蜂" },
  [2397] = { "蜜背巢母" },
  [2398] = { "蜜背收割者" },
  [2400] = { "波涛之刃剑鱼人", "波涛之刃剑鱼人是一支古老的深海战斗种族，徜徉于海洋中最深邃最危险的地带。" },
  [2401] = { "波涛之刃剑鱼人（典范）", "波涛之刃剑鱼人是一支古老的深海战斗种族，徜徉于海洋中最深邃最危险的地带。" },
  [2404] = { "造物密院" },
  [2405] = { "祭仪密院" },
  [2406] = { "魂选密院" },
  [2407] = { "晋升者", "格里恩历经艰难险阻，最终净化了凡人的负担后，会获得参加晋升仪式的资格，从而获得双翼，并向执政官发誓，永远为她效忠。" },
  [2408] = { "黑暗格里恩" },
  [2410] = { "不朽军团", "很久以前，兵主建立了玛卓克萨斯的五大密院，希望借此训练出最终极的战斗力。这支坚强的部队运用着力量、智慧和计谋，发誓守护暗影界，抵御一切威胁。" },
  [2411] = { "顽石军团" },
  [2412] = { "堕罪堡" },
  [2413] = { "收割者之庭", "在德纳修斯大帝统治了无数时代后，雷文德斯的权力现在属于整个收割者之庭。这些温西尔贵族承担着救赎骄傲之魂这一神圣的使命。" },
  [2414] = { "暗影国度" },
  [2415] = { "莱加尼", "这群魔古对泰坦守护者莱十分忠诚，他们的使命是击退来犯的恩佐斯的爪牙，守护纳拉克煞引擎。" },
  [2416] = { "莱加尼（典范）", "这群魔古对泰坦守护者莱十分忠诚，他们的使命是击退来犯的恩佐斯的爪牙，守护纳拉克煞引擎。" },
  [2417] = { "奥丹姆联军", "奥丹姆联军是由托维尔人牵头建立的松散同盟，建立的目的是为了击退敌军，保护起源熔炉。" },
  [2418] = { "奥丹姆联军（典范）", "奥丹姆联军是由托维尔人牵头建立的松散同盟，建立的目的是为了击退敌军，保护起源熔炉。" },
  [2419] = { "恩佐斯" },
  [2422] = { "法夜", "荒猎团在危急时刻受到了寒冬女王的召唤，他们召集了全炽蓝仙野最优秀的男女猎手。面对着心能枯竭和重重危险，荒猎团已经准备好守护这片森林。" },
  [2427] = { "亚基宝宝" },
  [2432] = { "威·娜莉", "威·娜莉对噬渊的了解远胜任何人，如果你赢得了她的尊敬，说不定她就会把信息分享一点给你。" },
  [2437] = { "托加斯特 -  守卫" },
  [2438] = { "托加斯特 -  囚犯" },
  [2439] = { "宣罪者", "这些档案员对指控者忠心耿耿，致力于复原并归档被宫务大臣和他的审判官盟友打碎的罪碑。" },
  [2440] = { "不朽军团（典范）", "很久以前，兵主建立了玛卓克萨斯的五大密院，希望借此训练出最终极的战斗力。这支坚强的部队运用着力量、智慧和计谋，发誓守护暗影界，抵御一切威胁。" },
  [2441] = { "晋升者（典范）", "格里恩历经艰难险阻，最终净化了凡人的负担后，会获得参加晋升仪式的资格，从而获得双翼，并向执政官发誓，永远为她效忠。" },
  [2442] = { "收割者之庭（典范）", "在德纳修斯大帝统治了无数时代后，雷文德斯的权力现在属于整个收割者之庭。这些温西尔贵族承担着救赎骄傲之魂这一神圣的使命。" },
  [2444] = { "荒猎团（典范）", "荒猎团在危急时刻受到了寒冬女王的召唤，他们召集了全炽蓝仙野最优秀的男女猎手。面对着心能枯竭和重重危险，荒猎团已经准备好守护这片森林。" },
  [2445] = { "灰烬王庭", "雷文德斯有了新的王庭，雷纳索尔王子希望联合整个暗影界的盟友，并增强他的盟约的影响力。" },
  [2446] = { "瓦丝琪女男爵", "这名锲而不舍的纳迦领袖始终在观察和审视。" },
  [2447] = { "月莓女勋爵", "月莓女勋爵是魅夜王庭中极其善变的成员，她喜欢恶作剧，影响力也很强。" },
  [2448] = { "米卡尼科斯", "身为晋升堡垒的掌炉宗师，米卡尼科斯总在构思新的发明。" },
  [2449] = { "女伯爵", "女伯爵是雷文德斯的一流聚会主持和社交名媛，她对公众的认知有强大的影响力。" },
  [2450] = { "亚历山德罗斯·莫格莱尼", "灰烬使者生前和死后都在战场上奔波，从未有过真正的安歇。" },
  [2451] = { "狩猎队长柯莱恩", "狩猎队长柯莱恩是一名强大的斗士，她可从没有耐心参加什么仪式。" },
  [2452] = { "文官阿得赖斯提斯", "这位坚忍的晋升者一直都在服务，他必须好好放松一下，就算是在聚会上也一样。" },
  [2453] = { "伦德尔和棍脸", "辛勤的工人应该得到奖赏。很少有人对堕罪堡的奉献能与伦德尔和棍脸相媲美。" },
  [2454] = { "丘法", "丘法和他的朋友都属于派对动物，从各种意义上来说都是如此。" },
  [2455] = { "地穴看守者卡希尔", "地穴看守者卡希尔固执己见，原则分明，总是为自己坚守的信条而战。" },
  [2456] = { "宗主艾莉奥瑟", "巨熊艾莉奥瑟是一名荒野之神，但她一点都不原始。" },
  [2457] = { "沃尔大师", "沃尔为照料伤逝剧场付出的心血有目共睹。" },
  [2458] = { "克雷雅和裴拉戈斯", "这对灵魂羁绊在一起时才最强大，他们的温西尔朋友也很乐意再看到他们。" },
  [2459] = { "西卡", "这名可敬的执事凭一己之力确保了整个晋升堡垒的正常运作。" },
  [2460] = { "石首", "我们南边纯朴的朋友控制了灰烬荒野的入口。" },
  [2461] = { "魔药设计师马里莱斯", "玛卓克萨斯的软泥科学大师的实验也许的确一团糟，但他总能想出解决的办法。" },
  [2462] = { "缝合大师", "缝合大师可以把血肉、骨头和心能熔铸到构造体里制作玛卓克萨斯的强大盟友，故而声名远播，他们退出了叛变的造物密院后，在屠夫区居住。" },
  [2463] = { "玛拉斯缪斯", "玛拉斯缪斯是个长得像蘑菇的炽蓝仙野居民，古老得难以想象。他是这个国度的生态系统的有机组成部分。你扶助森林的意愿软化了他身体里最像是心的构造，而这里总有很多的活儿等着完成。" },
  [2464] = { "魅夜王庭", "心能枯竭和德鲁斯特入侵占用了寒冬女王和荒猎团的大量注意力。现在只能依靠魅夜王庭的宗主来保护灵种，并保护林地。" },
  [2465] = { "荒猎团", "荒猎团在危急时刻受到了寒冬女王的召唤，他们召集了全炽蓝仙野最优秀的男女猎手。面对着心能枯竭和重重危险，荒猎团已经准备好守护这片森林。" },
  [2468] = { "刻希亚" },
  [2469] = { "分形知识", "施放创生的奥秘。" },
  [2470] = { "死亡先锋军", "暗影界四大盟约为突击统御圣所而结成的联军。" },
  [2471] = { "死亡先锋军（典范）", "暗影界四大盟约为突击统御圣所而结成的联军。" },
  [2472] = { "档案员卷宗", "刻希亚的侍神者全心全意地研究着来自暗影界各处的圣物。他们在档案员的领导下，投入到找回失散在刻希亚各处的圣物的工作中。这些圣物在渊誓大军入侵后散失了。" },
  [2473] = { "档案员卷宗（典范）", "刻希亚的侍神者全心全意地研究着来自暗影界各处的圣物。他们在档案员的领导下，投入到找回失散在刻希亚各处的圣物的工作中。这些圣物在渊誓大军入侵后散失了。" },
  [2474] = { "威·娜莉（典范）", "威·娜莉对噬渊的了解远胜任何人，如果你赢得了她的尊敬，说不定她就会把信息分享一点给你。" },
  [2478] = { "开悟者", "开悟者以前是艾财团的成员，但他们已经放弃了对利润和荣耀的追求，转而虔心侍奉初诞者。获得开悟者的青睐后，他们也许会乐意分享自己收集的知识。" },
  [2479] = { "开悟者（典范）", "开悟者以前是艾财团的成员，但他们已经放弃了对利润和荣耀的追求，转而虔心侍奉初诞者。获得开悟者的青睐后，他们也许会乐意分享自己收集的知识。" },
  [2480] = { "自动体" },
  [2502] = { "扎雷殁提斯引诱的怪物" },
  [2503] = { "马鲁克半人马", "各个半人马氏族遨游于欧恩哈拉平原。他们听取轻风的召唤，探求狩猎的刺激。" },
  [2504] = { "马鲁克半人马（典范）", "各个半人马氏族遨游于欧恩哈拉平原。他们听取轻风的召唤，探求狩猎的刺激。" },
  [2506] = { "巨龙时代" },
  [2507] = { "龙鳞探险队", "探险者协会和神圣遗物学会联合组成的探险队，他们是一群勇敢无畏的冒险者、学者和匠人，想发现巨龙群岛的万千奥秘。" },
  [2508] = { "龙鳞探险队（典范）", "探险者协会和神圣遗物学会联合组成的探险队，他们是一群勇敢无畏的冒险者、学者和匠人，想发现巨龙群岛的万千奥秘。" },
  [2509] = { "席卡尔氏族" },
  [2510] = { "瓦德拉肯联军", "瓦德拉肯联军的大本营位于其最古老的城市，象征着所有龙族力量的结合体。他们不仅要保护自己的家园——这片群岛，还要保护整个艾泽拉斯。" },
  [2511] = { "伊斯卡拉海象人", "伊斯卡拉海象人已经在巨龙群岛上生活了许多世代，他们和谐共处，热衷于讲述周遭世界的故事。" },
  [2512] = { "艾拉格氏族" },
  [2513] = { "欧恩伊尔氏族" },
  [2514] = { "拜荒者" },
  [2516] = { "贾拉丁" },
  [2517] = { "拉希奥", "长久以来，拉希奥的目标都专注于保护艾泽拉斯，现在，他的目光转向了黑龙军团的未来……以及他的宿命。" },
  [2518] = { "萨贝里安", "萨贝里安培养了新一代未被腐化的黑龙，而且为了保护他们不惜付出一切。" },
  [2519] = { "求索者" },
  [2520] = { "诺库德氏族" },
  [2521] = { "诺库德氏族（典范）" },
  [2522] = { "提莱氏族" },
  [2523] = { "暗爪营", "暗爪营的领袖是勇敢的鳞长欣戴赛什，他们受训成为黑龙军团的秘密武器。如今，无论遇到什么样的绝境，这些龙希尔都可以利用自己的战技来扭转战局。" },
  [2524] = { "黑卫营", "暗爪营的领袖是坚韧的鳞长阿苏拉泰，他们受训成为黑龙军团的护盾。如今，无论遇到什么样的绝境，这些龙希尔都可以利用自己的战技来守护需要帮助的人。" },
  [2525] = { "火元素" },
  [2526] = { "冬裘熊怪", "冬裘熊怪使用的语言似乎没人能听懂。也许将来人们会得知更多的奥秘。" },
  [2542] = { "尤克赫尔氏族" },
  [2544] = { "工匠商盟 - 巨龙群岛支部" },
  [2550] = { "钴蓝集所", "钴蓝集所曾是蓝龙用奥术魔法构建神器造物的地方。现在这里落入了碎裂之焰的手上，他们企图将这里的魔法用于战争。" },
  [2551] = { "伊斯卡拉海象人（典范）", "伊斯卡拉海象人已经在巨龙群岛上生活了许多世代，他们和谐共处，热衷于讲述周遭世界的故事。" },
  [2552] = { "瓦德拉肯联军（典范）", "瓦德拉肯联军的大本营位于其最古老的城市，象征着所有龙族力量的结合体。他们不仅要保护自己的家园——这片群岛，还要保护整个艾泽拉斯。" },
  [2553] = { "索莉多米", "索莉多米的时光旅行者们穿行于时间流之间，保护我们的世界不受无穷的平行宇宙的侵袭。当我们的时间线遭受时光袭击，或者即将分崩离析之时，索莉多米会率领众人维系秩序。" },
  [2554] = { "托古斯氏族" },
  [2555] = { "凯甘氏族" },
  [2564] = { "峈姆鼹鼠人", "鼹鼠人城镇峈姆位于巨龙群岛地下的查拉雷克洞窟深处。这些友善的商人以其热情好客的性格、灵敏的嗅觉和奇特的以物易物贸易系统而闻名。" },
  [2565] = { "峈姆鼹鼠人（典范）", "鼹鼠人城镇峈姆位于巨龙群岛地下的查拉雷克洞窟深处。这些友善的商人以其热情好客的性格、灵敏的嗅觉和奇特的以物易物贸易系统而闻名。" },
  [2568] = { "格里梅罗格竞速者", "布里谷尔不会让随便什么人跟滑仔一起竞技。你能证明自己是个合格的蜗牛训练师吗？" },
  [2569] = { "地心之战" },
  [2570] = { "陨圣峪阿拉希人", "陨圣峪远征队的阿拉希人在卡兹阿加的地下发现了名为贝雷达尔的星星，并保护它免受许多威胁的侵害。他们与远隔重洋的帝国失去了联系，凭借对神圣烈焰的信仰之力，在此地建起了新的家园。" },
  [2574] = { "梦境守望者", "许多种族构成的同盟，誓要守护翡翠梦境，抗击所有威胁。" },
  [2575] = { "梦境守望者（典范）", "许多种族构成的同盟，誓要守护翡翠梦境，抗击所有威胁。" },
  [2576] = { "烈焰德鲁伊" },
  [2590] = { "多恩诺嘉尔议会", "多恩诺嘉尔议会在础石大厅商议政务，在议会护持麦里克斯的领导下，他们的决策关乎到多恩岛上的每一个土灵。" },
  [2593] = { "桶腿船团", "一群不合群的海盗，充满自由精神，聚集在桶腿船长的旗下。" },
  [2594] = { "邃渊协盟", "喧鸣深窟各地都有疏于照看的机械设备等待着维修。在机语者发挥技术专长的同时，狗头人会回收遗落的零件。他们欢迎所有志在探索与重建的人们前来相助。" },
  [2595] = { "玄夜会" },
  [2596] = { "斩离之丝（典范）", "并非所有人都对安苏雷克女王的残酷统治忍气吞声。斩离之丝正在幕后秘密地谋划，打算从内部瓦解安苏雷克织造的铁律。" },
  [2600] = { "斩离之丝", "并非所有人都对安苏雷克女王的残酷统治忍气吞声。斩离之丝正在幕后秘密地谋划，打算从内部瓦解安苏雷克织造的铁律。" },
  [2601] = { "纺丝者", "曾经的皇家纺织者寡妇阿拉克奈，如今正以敏锐的目光监视着自己过去的家园。她编织了一张由纺崽和间谍组成的网络，鲜有动静能够逃过她的目光。" },
  [2602] = { "晦幽集市", "控制千丝之城的晦幽集市的生物行为。" },
  [2604] = { "桶腿船团（典范）", "一群不合群的海盗，充满自由精神，聚集在桶腿船长的旗下。" },
  [2605] = { "将军", "阿努巴扎尔曾经是艾基-卡赫特声威显赫的军事领袖，安苏雷克却将其冷落，只宠幸自己的扬升者。这等轻慢岂能容忍？" },
  [2606] = { "高耸虚居", "控制千丝之城的高耸虚居的生物行为。" },
  [2607] = { "宰相", "深入狼穴的执行官尼兹雷克随侍在安苏雷克女王左右，担任她最忠心耿耿的顾问。幸好安苏雷克尚未发现，在剩下的时间里，尼兹雷克都在为了终结她的统治而奔走。" },
  [2609] = { "潜暗之峡", "控制千丝之城的潜暗之峡的生物行为。" },
  [2610] = { "艾基-卡赫特蛛魔（永远敌对）（隐藏）", "控制永远敌对的蛛魔的生物行为。像怪物一样行动，但其他蛛魔不会攻击（即使是对玩家友善）。用于绝大部分蛛魔敌人。" },
  [2611] = { "陨圣峪阿拉希人（典范）", "陨圣峪远征队的阿拉希人在卡兹阿加的地下发现了名为贝雷达尔的星星，并保护它免受许多威胁的侵害。他们与远隔重洋的帝国失去了联系，凭借对神圣烈焰的信仰之力，他们在此地建起了新的家园。" },
  [2612] = { "多恩诺嘉尔议会（典范）", "多恩诺嘉尔议会在础石大厅商议政务，在议会护持麦里克斯的领导下，他们的决策关乎到多恩岛上的每一个土灵。" },
  [2613] = { "邃渊协盟（典范）", "喧鸣深窟各地都有疏于照看的机械设备等待着维修。在机语者发挥技术专长的同时，狗头人会回收遗落的零件。他们欢迎所有志在探索与重建的人们前来相助。" },
  [2614] = { "坚铸要塞" },
  [2615] = { "艾泽拉斯档案馆", "龙鳞探险队的一个学者组织，致力于为子孙后代保护文物。" },
  [2616] = { "桶腿痛击者" },
  [2635] = { "束丝之集", "控制千丝之城的束丝之集的生物行为。" },
  [2637] = { "玩家,土灵联盟" },
  [2638] = { "玩家,土灵部落" },
  [2640] = { "布莱恩·铜须", "值得信赖的地下堡伙伴" },
  [2644] = { "地下堡：第1赛季" },
  [2645] = { "土灵" },
  [2647] = { "宰相（典范）", "深入狼穴的执行官尼兹雷克随侍在安苏雷克女王左右，担任她最忠心耿耿的顾问。幸好安苏雷克尚未发现，在剩下的时间里，尼兹雷克都在为了终结她的统治而奔走。" },
  [2648] = { "纺丝者（典范）", "曾经的皇家纺织者寡妇阿拉克奈，如今正以敏锐的目光监视着自己过去的家园。她编织了一张由纺崽和间谍组成的网络，鲜有动静能够逃过她的目光。" },
  [2649] = { "将军（典范）", "阿努巴扎尔曾经是艾基-卡赫特声威显赫的军事领袖，安苏雷克却将其冷落，只宠幸自己的扬升者。这等轻慢岂能容忍？" },
  [2652] = { "暗索执法", "加斯特·加里维克斯雇来“保护”安德麦人民与财产的佣兵。" },
  [2653] = { "安德麦财阀", "安德麦不同于其他城镇，没有国王和酋长，只有各大财阀。每个人都想成为财阀的一份子。这可比国王更好，因为国王只能有一位。安德麦有许多财阀，而他们都需要朋友。" },
  [2658] = { "卡雷什托拉斯", "由掮灵和虚灵的财团组成的联合团体，正为了实现难以企及的目标而奔走。他们希望从诸界吞噬者口中拯救自己覆灭的世界，哪怕只是一个面向。" },
  [2659] = { "卡雷什托拉斯（典范）", "由掮灵和虚灵的财团组成的联合团体，正为了实现难以企及的目标而奔走。他们希望从诸界吞噬者口中拯救自己覆灭的世界，哪怕只是一个面向。" },
  [2663] = { "米尔拉", "米尔拉离开了沃顿的故乡，她决定成为一名行商，与她最好的朋友——两只名为朵利和朵特的羊驼——一起环游世界。" },
  [2664] = { "弗林·法温德", "弗林曾是库尔提拉斯附近的一名海盗船长，但他后来许下诺言要（在钱到位的情况下）为联盟服务。" },
  [2665] = { "莉莉斯塔萨", "莉莉斯塔萨居住在巨龙群岛的红玉新生圣地，但她经常云游四海，探访有趣的地方。" },
  [2666] = { "烘烤与夸耀", "博罗格罗夫本地的咖啡店。" },
  [2667] = { "安德麦财阀（典范）", "安德麦不同于其他城镇，没有国王和酋长，只有各大财阀。每个人都想成为财阀的一份子。这可比国王更好，因为国王只能有一位。安德麦有许多财阀，而他们都需要朋友。" },
  [2668] = { "暗索处理服务（典范）", "暗索处理服务为加里维克斯卖命时没能交到朋友，但地精不会轻言放弃。他们重塑了品牌，端正了态度，毕竟生意归生意，对吧？" },
  [2669] = { "暗索处理服务", "暗索处理服务为加里维克斯卖命时没能交到朋友，但地精不会轻言放弃。他们重塑了品牌，端正了态度，毕竟生意归生意，对吧？" },
  [2670] = { "风险投资公司（典范）", "风险投资公司的名声不算很好，但采收、开掘和钻取的本事无人能及。你想要衣冠楚楚，不如去找个读书会吧。你想弄到原材料，就得找风险投资公司。" },
  [2671] = { "风险投资公司", "风险投资公司的名声不算很好，但采收、开掘和钻取的本事无人能及。你想要衣冠楚楚，不如去找个读书会吧。你想弄到原材料，就得找风险投资公司。" },
  [2672] = { "锈水财阀（典范）", "锈水财阀经历过超乎寻常的兴衰起伏，但他们营建和发明的本事举世无双。不论是城市、泳池玩具还是[绝密内容]，锈水出品必属精品。" },
  [2673] = { "锈水财阀", "锈水财阀经历过超乎寻常的兴衰起伏，但他们营建和发明的本事举世无双。不论是城市、泳池玩具还是[绝密内容]，锈水出品必属精品。" },
  [2674] = { "黑水财阀（典范）", "新晋的黑水财阀曾经是称霸海洋的强盗，但他们早已在航运和奢华度假行业中呼风唤雨了。不论什么货物，不论何时何地，他们都能运送，完全清白合法。" },
  [2675] = { "黑水财阀", "新晋的黑水财阀曾经是称霸海洋的强盗，但他们早已在航运和奢华度假行业中呼风唤雨了。不论什么货物，不论何时何地，他们都能运送，完全清白合法。" },
  [2676] = { "热砂财阀（典范）", "热砂财阀或许是安德麦最古老最庞大的财阀，艾泽拉斯和彼岸世界的几乎每个行当都被他们插过一手。如今随着诺格弗格的得势，他们炼金秘法的威名人尽皆知。" },
  [2677] = { "热砂财阀", "热砂财阀或许是安德麦最古老最庞大的财阀，艾泽拉斯和彼岸世界的几乎每个行当都被他们插过一手。如今随着诺格弗格的得势，他们炼金秘法的威名人尽皆知。" },
  [2683] = { "地下堡：第2赛季" },
  [2684] = { "加乐宫会员奖励俱乐部（典范）", "加乐宫已经易主，呃，即将易主。等到易主之后，你肯定想与他们和睦相处吧？一起将加乐宫打造得更美好，结交一些新的朋友吧。" },
  [2685] = { "加乐宫会员奖励俱乐部", "加乐宫已经易主，呃，即将易主。等到易主之后，你肯定想与他们和睦相处吧？一起将加乐宫打造得更美好，结交一些新的朋友吧。" },
  [2688] = { "圣焰之耀", "陨圣峪危在旦夕、守军势单力孤之际，壮勇之士响应了武装的号召，组建了圣焰之耀。他们欢迎所有盟友一同巩固陨圣峪的防御。" },
  [2689] = { "圣焰之耀（典范）", "陨圣峪危在旦夕、守军势单力孤之际，壮勇之士响应了武装的号召，组建了圣焰之耀。他们欢迎所有盟友一同巩固陨圣峪的防御。" },
  [2692] = { "风险投资公司" },
  [2693] = { "地下堡行者的旅程（第1赛季）" },
  [2696] = { "阿曼尼部族", "阿曼尼在数千年间征服并占据了东部王国的大部分领土，但随着精灵和人类出兵殖民这片土地，他们被迫退守至如今的祖阿曼。" },
  [2698] = { "至暗之夜" },
  [2699] = { "奇点特勤", "在虚影风暴这充满恐怖与暴力的漩涡中，鲜有人拥有生存下来的勇气。由乌布里克魔导师和朗多雷召集的奇点特勤，在这片可怕的土地上吸纳了所有敢于挺身反抗萨拉塔斯的人。" },
  [2704] = { "哈籁提", "在女神之歌回响的召唤下，哈籁提一族来到了哈籁恩达尔，守护她曾经栖居的摇篮，盼望着她归来的那一日。" },
  [2705] = { "阿曼尼部族（典范）" },
  [2706] = { "枯木部族" },
  [2709] = { "圣光先锋军" },
  [2710] = { "银月宫廷", "凭借优雅、智慧与政治手腕，宫廷确保银月城的光芒永恒闪耀，卓尔不群。" },
  [2711] = { "魔导师", "银月城首屈一指的魔法使用者。魔导师是才华横溢的辛多雷，对奥术技艺拥有极高的掌控力，加之经过数百年的钻研，他们的智慧无比敏锐。" },
  [2712] = { "血骑士", "银月城的圣骑士部队。作为太阳眷顾的坚毅英雄与天命勇士，他们追随女伯爵莉亚德琳征战沙场，铲除辛多雷的敌人。" },
  [2713] = { "远行者", "辛多雷的精英游侠，正式肩负守卫永歌森林的林地、边境与荒野之重任。" },
  [2714] = { "径巷之影", "卑劣。贪婪。但在棘手的情况下却极其有用。你很少听到有人提及“径巷之影”，但可以肯定的是，银月城中几乎每个人都曾与他们打过交道。" },
  [2720] = { "银月城" },
  [2722] = { "地下堡：第3赛季" },
  [2725] = { "奇点特勤（典范）", "在虚影风暴这充满恐怖与暴力的漩涡中，鲜有人拥有生存下来的勇气。由乌布里克魔导师和朗多雷召集的奇点特勤，在这片可怕的土地上吸纳了所有敢于挺身反抗萨拉塔斯的人。" },
  [2726] = { "哈籁提（典范）" },
  [2727] = { "银月宫廷（典范）" },
  [2728] = { "玩家，部落哈籁尼尔" },
  [2729] = { "玩家，联盟哈籁尼尔" },
  [2736] = { "法力熔炉破袭队", "卡雷什托拉斯致力于团结垂死母星上的人们，但有些成员更喜欢采取直截了当的手段。不论是秘密行动还是卑鄙计俩，只要能粉碎萨哈达尔的势力，法力熔炉破袭队无所不用其极。" },
  [2739] = { "地下堡：宝匣钥匙碎片转化" },
  [2742] = { "地下堡：第1赛季" },
  [2744] = { "瓦莉拉·萨古纳尔", "值得信赖的地下堡伙伴" },
  [2764] = { "狩猎：第1赛季", "艾泽拉斯四面受敌之际，阿斯塔洛·血誓发现了一种保卫银月城的特殊方式。" },
  [2766] = { "搏击竞技场", "一群格斗狂人从各地收罗来了各种生物，将它们放置在血腥的竞技场中与部落的英雄们进行生死搏斗。" },
  [2767] = { "比兹莫搏击俱乐部", "一群格斗狂人从各地收罗来了各种生物，将它们放置在血腥的竞技场中与联盟的英雄们进行生死搏斗。" },
  [2770] = { "屠戮角斗", "在虚影风暴深处，维迪奥斯与兹尔丹之间的战争仍在肆虐。" },
  [2771] = { "祖尔加拉的部队（典范）", "在祖尔加拉的领导下，暗松、枯木、恶齿和阿曼尼士兵结成了统一战线。这支大军将抗击玛拉卡斯和乌拉特克的战火烧到了盘卷蛇岛——阿塔乌特克。" },
  [2772] = { "祖尔加拉的部队", "在祖尔加拉的领导下，暗松、枯木、恶齿和阿曼尼士兵结成了统一战线。这支大军将抗击玛拉卡斯和乌拉特克的战火烧到了盘卷蛇岛——阿塔乌特克。" },
  [2773] = { "托卡船长", "托卡船长的船被大白蟒吞噬了，他的船员也因乌拉特克的诅咒而堕落。如果你能帮他复仇，他就会向你传授烈毒钓鱼的秘诀。" },
  [2774] = { "屠戮角斗（典范）", "在虚影风暴深处，维迪奥斯与兹尔丹之间的战争仍在肆虐。" },
  [2780] = { "暗松部族" },
  [2781] = { "恶齿部族" },
  [2792] = { "仪式场地", "虚空袭击过后的乱局助长了敌人的气焰，使其妄图通过黑暗仪式攫取力量。我们必须肃清这些魔力肆虐的场地。" },
  [2793] = { "仪式场地（典范）" },
  [2796] = { "地下堡：第2赛季" },
  [2808] = { "猎捕手的旅程", "艾泽拉斯四面受敌之际，阿斯塔洛·血誓发现了一种保卫银月城的特殊方式。" },
  [2836] = { "金多赞的迷宫" },
  [2838] = { "亚基研究飞地", "这些圣骑士立誓效忠银月城，潜心研究亚基带来的威胁，力求洞悉敌人的本质，确保银月城永远有备无患。" },
  [2839] = { "地下堡：第3赛季" },
};
